const wc = {
  0: ['Clear sky', '☀️'], 1: ['Mainly clear', '🌤️'], 2: ['Partly cloudy', '⛅'],
  3: ['Overcast', '☁️'], 45: ['Foggy', '🌫️'], 48: ['Foggy', '🌫️'],
  51: ['Light drizzle', '🌦️'], 53: ['Drizzle', '🌦️'], 55: ['Drizzle', '🌦️'],
  61: ['Light rain', '🌧️'], 63: ['Rain', '🌧️'], 65: ['Heavy rain', '🌧️'],
  71: ['Snow', '🌨️'], 80: ['Rain showers', '🌦️'], 81: ['Rain showers', '🌦️'],
  82: ['Heavy showers', '⛈️'], 95: ['Thunderstorm', '⛈️'], 96: ['Thunderstorm', '⛈️'], 99: ['Thunderstorm', '⛈️'],
};

// Weather
const w = ($('Get Weather').first().json.current) || {};
const daily = ($('Get Weather').first().json.daily) || {};
const desc = wc[w.weather_code] ? wc[w.weather_code][0] : 'Mixed skies';
const temp = w.temperature_2m != null ? Math.round(w.temperature_2m) : '?';
const hi = daily.temperature_2m_max ? Math.round(daily.temperature_2m_max[0]) : null;
const lo = daily.temperature_2m_min ? Math.round(daily.temperature_2m_min[0]) : null;
let weatherLine = `${desc}, ${temp}°C`;
if (hi != null && lo != null) weatherLine += ` (H:${hi}° L:${lo}°)`;

// News (Hacker News front page)
const articles = (($('Get News').first().json.hits) || []).filter(a => a && a.title).slice(0, 4);
const newsBlock = articles.length
  ? articles.map((a, i) => {
      const link = a.url || `https://news.ycombinator.com/item?id=${a.objectID}`;
      return `${i + 1}. ${a.title}\n   ${link}`;
    }).join('\n')
  : 'No headlines available right now.';

// Motivation
const quotes = [
  'Small steps every day add up to big results.',
  'Make today ridiculously amazing.',
  'You’ve got everything you need to make today great.',
  'Progress, not perfection.',
  'One good thing at a time — you’ve got this!',
];
const quote = quotes[Math.floor(Math.random() * quotes.length)];

const nowIst = DateTime.now().setZone('Asia/Kolkata');
const today = nowIst.toFormat('cccc, LLL d');
const hour = nowIst.hour;
let greeting, emoji;
if (hour < 12) { greeting = 'Good morning'; emoji = '🌅'; }
else if (hour < 17) { greeting = 'Good afternoon'; emoji = '☀️'; }
else if (hour < 21) { greeting = 'Good evening'; emoji = '🌆'; }
else { greeting = 'Good night'; emoji = '🌙'; }
const timeLabel = nowIst.toFormat('h:mm a');

const message = [
  `${greeting}! Here's your digest for ${today}, ${timeLabel} ${emoji}`,
  '',
  `🌤️ Weather\n${weatherLine}`,
  '',
  `📰 Top News\n${newsBlock}`,
  '',
  `💡 ${quote}`,
].join('\n');

return [{ json: { subject: `Your Digest — ${today}, ${timeLabel}`, message } }];
